INSERT INTO compendium_match_aliases (ruleset_id, class_id, item_kind, source_name, target_name, source_slug, target_slug, match_strategy, rename_via, priority, status, evidence_ref, notes)
SELECT 'pf2e-remaster', NULL, item_kind, source_name, target_name, wgi_sluggify(source_name), wgi_sluggify(target_name), 'exact', 'exact', 100, 'active', 'WG snapshot public.' || source_table || '#' || wg_id::text || '; PF2e source ' || pf2e_source_path, 'Unique case-insensitive exact-name match in the source document type; no inference.'
FROM mappings m
WHERE NOT EXISTS (
  SELECT 1 FROM compendium_match_aliases a
  WHERE a.ruleset_id = 'pf2e-remaster'
    AND a.item_kind = m.item_kind
    AND a.source_slug = wgi_sluggify(m.source_name)
    AND a.target_slug = wgi_sluggify(m.target_name)
    AND COALESCE(a.class_id, '') = ''
 );
COMMIT;

